import{_ as t,o as e,c as o,a0 as c}from"./chunks/framework.Bmhw_dvp.js";const _=JSON.parse('{"title":"环境变量","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/env.md","filePath":"advanced/env.md","lastUpdated":1791088295000}'),a={name:"advanced/env.md"};function r(s,d,i,n,l,p){return e(),o("div",null,[...d[0]||(d[0]=[c(`<h1 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to &quot;环境变量&quot;">​</a></h1><p>ZViewer 的配置分两类：启动时读取的环境变量，以及运行时可改、存在数据库里的设置。这一页先列后端和前端的变量，再说明数据库切换与运行时可调项。</p><h2 id="后端" tabindex="-1">后端 <a class="header-anchor" href="#后端" aria-label="Permalink to &quot;后端&quot;">​</a></h2><p>后端在启动时读取这些变量。未设置时，服务会采用第三列的默认值。</p><table tabindex="0"><thead><tr><th>变量</th><th>说明</th><th>默认值</th></tr></thead><tbody><tr><td><code>PORT</code></td><td>后端服务端口</td><td><code>3333</code></td></tr><tr><td><code>HOST</code></td><td>监听地址</td><td>空（IPv4/IPv6 双栈）</td></tr><tr><td><code>NODE_ENV</code></td><td>运行环境</td><td><code>production</code></td></tr><tr><td><code>DATABASE_URL</code></td><td>SQLite 文件路径或 PostgreSQL 连接串</td><td><code>&lt;config&gt;/dev.sqlite</code></td></tr><tr><td><code>CONFIG_DIR</code></td><td>数据根目录</td><td><code>&lt;project-root&gt;/config</code></td></tr><tr><td><code>CORS_ORIGIN</code></td><td>CORS 允许来源，多个逗号分隔</td><td><code>*</code></td></tr><tr><td><code>JWT_ACCESS_SECRET</code></td><td>Access Token 密钥（生产环境宜显式设置）</td><td>自动生成并写入 <code>config/jwt-secrets.json</code></td></tr><tr><td><code>JWT_REFRESH_SECRET</code></td><td>Refresh Token 密钥（生产环境宜显式设置）</td><td>同上</td></tr><tr><td><code>JWT_ACCESS_EXPIRES_IN</code></td><td>Access Token 有效期</td><td><code>1h</code></td></tr><tr><td><code>JWT_REFRESH_EXPIRES_IN</code></td><td>Refresh Token 有效期</td><td><code>30d</code>（guest 恒为 1h / 7d）</td></tr><tr><td><code>RTMP_PORT</code></td><td>RTMP 推流端口</td><td><code>3334</code></td></tr><tr><td><code>HTTP_FLV_PORT</code></td><td>HTTP-FLV 拉流端口（内部，经 <code>/live</code> 反代）</td><td><code>3335</code></td></tr><tr><td><code>STREAM_PUSH_ENABLED</code></td><td>设为 <code>0</code> 时完全不启动推流服务（NMS），不监听 3334/3335</td><td>开启</td></tr><tr><td><code>SERVER_HOST</code></td><td>生成 OBS 推流地址时使用的主机名</td><td>空（取请求 Host 去端口）</td></tr><tr><td><code>ENABLE_LOGIN_LOCK</code></td><td>启用登录失败锁定（5 次锁 15 分钟）</td><td>关闭</td></tr></tbody></table><p>单文件版的配置写入 <code>config/</code> 目录下的环境文件；Docker 通过 <code>-e</code> 或 compose <code>environment</code> 注入。</p><p><strong>JWT 密钥自举</strong>：未设环境变量时读 <code>config/jwt-secrets.json</code>（长度 ≥32 才采信），仍无则自动生成 64 位 hex 写回文件。首次启动无需配置；生产环境固定密钥可避免重启后登录态失效。</p><h2 id="语音聊天-livekit" tabindex="-1">语音聊天（LiveKit） <a class="header-anchor" href="#语音聊天-livekit" aria-label="Permalink to &quot;语音聊天（LiveKit）&quot;">​</a></h2><p>语音聊天由内嵌的 LiveKit 服务承载（LiveKit 是开源的 WebRTC 实时通信服务）。默认无需任何配置：信令经主端口的 <code>/rtc</code> 路径反代，媒体流走 <code>3333/udp</code>，公网 IP 经 LiveKit 原生 STUN（一种通过向外部服务查询来自动发现自身公网地址的机制）自动发现。以下变量用于特殊网络环境的调整。</p><table tabindex="0"><thead><tr><th>变量</th><th>说明</th><th>默认值</th></tr></thead><tbody><tr><td><code>LIVEKIT_API_KEY</code></td><td>接入凭证的签名密钥</td><td><code>devkey</code></td></tr><tr><td><code>LIVEKIT_API_SECRET</code></td><td>接入凭证的签名密钥</td><td><code>zviewer-dev-secret</code></td></tr><tr><td><code>LIVEKIT_API_HOST</code></td><td>服务端 API 与 <code>/rtc</code> 反代的上游地址</td><td><code>http://127.0.0.1:3336</code></td></tr><tr><td><code>LIVEKIT_URL</code></td><td>客户端连接地址。留空时按请求头推导，跟随页面域名与协议</td><td>空（自动推导）</td></tr><tr><td><code>LIVEKIT_EXTERNAL</code></td><td>设为 <code>1</code> 时跳过内嵌服务，连接外置 LiveKit</td><td><code>0</code></td></tr><tr><td><code>LIVEKIT_BIND</code></td><td>内嵌服务的监听地址</td><td><code>::</code>（双栈）</td></tr><tr><td><code>LIVEKIT_NODE_IP</code></td><td>ICE 广播地址（告知客户端向哪个地址建立媒体连接）。留空时自动启用 STUN 外部 IP 发现（要求服务器可出网）；NAT 复杂环境可手动指定公网 IP</td><td>空（自动）</td></tr><tr><td><code>LIVEKIT_RTC_TCP_PORT</code></td><td>语音传输模式为 TCP 时开启的 ICE/TCP 直连端口，供 UDP 被拦截的网络兜底；模式本身在管理端「基础设置 → 语音传输模式」切换</td><td><code>3337</code></td></tr><tr><td><code>LIVEKIT_TURN_DOMAIN</code></td><td>TURN/TLS 域名。与 <code>LIVEKIT_TURN_CERT</code>、<code>LIVEKIT_TURN_KEY</code> 同时设置时，启用 TCP 5349 兜底中继，供 UDP 被拦截的网络使用；域名寻址不依赖公网 IP</td><td>—</td></tr><tr><td><code>LIVEKIT_TURN_CERT</code></td><td>TURN TLS 证书路径（必须正式证书，自签证书不被浏览器 WebRTC 信任）</td><td>—</td></tr><tr><td><code>LIVEKIT_TURN_KEY</code></td><td>TURN TLS 私钥路径</td><td>—</td></tr></tbody></table><p>UDP 直连与 TURN 中继并行尝试：TURN 只作兜底，不影响直连成功时的低延迟。变量之间的完整关系与启动过程见<a href="/advanced/voice">语音聊天链路</a>。</p><h2 id="前端构建" tabindex="-1">前端构建 <a class="header-anchor" href="#前端构建" aria-label="Permalink to &quot;前端构建&quot;">​</a></h2><p>前端构建期的变量在打包时被写进产物，运行时就改不了了。</p><table tabindex="0"><thead><tr><th>变量</th><th>说明</th><th>默认值</th></tr></thead><tbody><tr><td><code>VITE_API_URL</code></td><td>API / Socket.IO 基础地址</td><td>空（<code>window.location.origin</code>）</td></tr><tr><td><code>VITE_FLV_BASE_URL</code></td><td>OBS 推流模式 HTTP-FLV 拉流基础地址</td><td><code>/live</code>（后端反代到 NMS）</td></tr><tr><td><code>VITE_RTMP_PORT</code></td><td>OBS 推流端口提示</td><td><code>3334</code></td></tr></tbody></table><p>这些变量在 <code>npm run build</code> 时固化，运行时不可改。开发模式下 Vite 会把 <code>/api</code>、<code>/socket.io</code>、<code>/live</code> 代理转发到后端，所以不需要配置 <code>VITE_API_URL</code>。</p><p>运行时若要改后端地址，可以在顶栏「自定义后端地址」里覆盖，值存于 localStorage：<code>zviewer-custom-api-url</code>、<code>zviewer-custom-socket-url</code>、<code>zviewer-custom-flv-base-url</code>、<code>zviewer-custom-rtmp-port</code>。</p><h2 id="数据库切换" tabindex="-1">数据库切换 <a class="header-anchor" href="#数据库切换" aria-label="Permalink to &quot;数据库切换&quot;">​</a></h2><p><code>DATABASE_URL</code> 接受两种形态，写法见下例。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># SQLite（默认，文件路径）</span></span>
<span class="line"><span>&lt;config&gt;/dev.sqlite</span></span>
<span class="line"><span></span></span>
<span class="line"><span># PostgreSQL（连接串）</span></span>
<span class="line"><span>postgres://user:password@host:5432/zviewer</span></span></code></pre></div><p>切换后首次启动会自动建表。SQLite 的数据需要手动迁移（<code>config/dev.sqlite</code> 是标准 SQLite 格式，可用常规工具导出导入）。数据库驱动 sql.js 是 wasm 实现，无需原生编译。</p><h2 id="运行时可调项-管理后台-非环境变量" tabindex="-1">运行时可调项（管理后台，非环境变量） <a class="header-anchor" href="#运行时可调项-管理后台-非环境变量" aria-label="Permalink to &quot;运行时可调项（管理后台，非环境变量）&quot;">​</a></h2><p>这些设置不在环境变量里，而是存在数据库中，通过管理后台修改。注册模式、建房模式、权限矩阵、功能开关（<code>dashDisabled</code> / <code>playsvideoEnabled</code> / <code>betaFeaturesEnabled</code>）、无人房间自动清理（<code>autoDeleteInactiveRooms</code> + <code>autoDeleteAfterHours</code>，默认 24 小时）、预发布更新接收等，均存库并通过 <code>/api/admin/settings</code> 修改，前端启动时经 <code>/api/auth/public-settings</code> 拉取。</p>`,22)])])}const h=t(a,[["render",r]]);export{_ as __pageData,h as default};
